package vn.hust.restaurant.view;
import java.awt.*;import javax.swing.*;import vn.hust.restaurant.config.AppContext;
public class ForgotPasswordDialog extends JDialog{private final AppContext ctx;private final JTextField identity=new JTextField(24),otp=new JTextField(10);private final JPasswordField p1=new JPasswordField(18),p2=new JPasswordField(18);public ForgotPasswordDialog(Frame owner,AppContext c){super(owner,"Quên mật khẩu",true);ctx=c;setSize(440,320);setLocationRelativeTo(owner);JPanel p=new JPanel(new GridLayout(0,2,8,8));p.setBorder(BorderFactory.createEmptyBorder(20,20,20,20));p.add(new JLabel("Username/Email/SĐT"));p.add(identity);JButton send=new JButton("Gửi OTP");p.add(send);p.add(new JLabel());p.add(new JLabel("Mã OTP"));p.add(otp);p.add(new JLabel("Mật khẩu mới"));p.add(p1);p.add(new JLabel("Nhập lại"));p.add(p2);JButton reset=new JButton("Đổi mật khẩu");p.add(reset);p.add(new JLabel());add(p);send.addActionListener(e->Ui.run(this,()->{String result=ctx.auth.requestOtp(identity.getText());Ui.info(this,"Đã tạo OTP. "+result);}));reset.addActionListener(e->Ui.run(this,()->{if(!java.util.Arrays.equals(p1.getPassword(),p2.getPassword()))throw new IllegalArgumentException("Hai mật khẩu không khớp");ctx.auth.reset(otp.getText(),new String(p1.getPassword()));Ui.info(this,"Đổi mật khẩu thành công");dispose();}));}}
